	UBOOL IsDirty() const { return DirtyMask & 1; }
	UBOOL IsTransient() const { return DirtyMask & UCONST_kTransientProfile; }

	void SetDirty()
	{
		DirtyMask = DirtyMask | 1;
	}

	void SetClean()
	{
		DirtyMask = DirtyMask & 254;
	}

	void SetTransient( UBOOL bNewValue )
	{
		if ( bNewValue )
			DirtyMask = DirtyMask | UCONST_kTransientProfile;
		else DirtyMask = DirtyMask & ~UCONST_kTransientProfile;
	}


